from gmpy2 import gcd, invert
from binascii import unhexlify

def int_to_bytes(i):
    h = hex(i)[2:]
    if len(h) % 2:
        h = '0' + h
    return bytes.fromhex(h)

def try_candidates(N, e, c):
    N = int(N)
    e = int(e)
    c = int(c)
    k = gcd(e, N-1)
    if k <= 1:
        return []
    results = []
    try:
        e_div_k = e // k
        N1_div_k = (N-1) // k
        inv = int(invert(e_div_k, N1_div_k))
        for i in range(k):
            d = inv + i*N1_div_k
            m = pow(c, d, N)
            mb = int_to_bytes(m)
            if b'flag{' in mb:
                results.append(mb.decode(errors='ignore'))
    except Exception as ex:
        pass
    return results

def parse_rsa_blocks(filename):
    items = []
    current = {}
    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if line.startswith('N = '):
                current['N'] = line[4:]
            elif line.startswith('e = '):
                current['e'] = line[4:]
            elif line.startswith('c = '):
                current['c'] = line[4:]
                if len(current) == 3:
                    items.append(current)
                    current = {}
    return items

if __name__ == '__main__':
    chals = parse_rsa_blocks('/home/ctfplayer/ctf_files/rsa_nc_chals.txt')
    outputs = []
    for chal in chals:
        res = try_candidates(chal['N'], chal['e'], chal['c'])
        for r in res:
            outputs.append(r)
    for o in outputs:
        print(o)

