import re

HOST = "crypto.chal.csaw.io"
PORT = 5000
SAMPLES = 10

def extract_params(lines):
    # expects a list of lines containing N, e, c
    N, e, c = None, None, None
    for line in lines:
        if line.startswith("N = "):
            N = int(line.split("= ")[1])
        elif line.startswith("e = "):
            e = int(line.split("= ")[1])
        elif line.startswith("c = "):
            c = int(line.split("= ")[1])
    if N is None or e is None or c is None:
        raise ValueError("Could not parse N, e, c in output: " + str(lines))
    return N, e, c

samples = []
for _ in range(SAMPLES):
    io = remote(HOST, PORT)
    io.recvuntil(b"> ")
    io.sendline(b"ciphertext_info")
    output = b""
    # We'll read until we see another prompt "> "
    while True:
        chunk = io.recv(timeout=1)
        if b"> " in chunk:
            output += chunk.split(b"> ")[0]
            break
        output += chunk
    io.close()
    lines = output.decode().strip().split("\n")
    # remove blank lines
    lines = [l.strip() for l in lines if l.strip()]
    # Find lines with 'N =', 'e =', 'c ='
    params = []
    for l in lines:
        if l.startswith('N =') or l.startswith('e =') or l.startswith('c ='):
            params.append(l)
    N, e, c = extract_params(params)
    samples.append( (N, e, c) )

print("Collected samples:")
for idx, (N, e, c) in enumerate(samples):
    print(f"Sample {idx}: N={N}, e={e}, c={c}")

print("\nChecking for repeated moduli or public exponents:")
Nset = set()
eset = set()
for (N, e, c) in samples:
    if N in Nset:
        print(f"Warning: Repeated modulus N = {N}")
    Nset.add(N)
    if e in eset:
        print(f"Note: Repeated e = {e}")
    eset.add(e)

print("\nChecking GCD(Ni-1, Nj-1) for all pairs:")
for i in range(SAMPLES):
    for j in range(i+1, SAMPLES):
        Ni, Nj = samples[i][0], samples[j][0]
        g = gcd(Ni-1, Nj-1)
        if g != 1:
            print(f"Nontrivial GCD(N_{i}-1, N_{j}-1) = {g}")
print("\nChecking GCD(Ni, Nj) for all pairs:")
for i in range(SAMPLES):
