            print(f"Shared prime between N_{i} and N_{j}. GCD(N_{i},N_{j}) = {g}")

from pwn import remote
from math import gcd

HOST = 'crypto.chal.csaw.io'
PORT = 5000
SAMPLES = 10

def get_sample():
    r = remote(HOST, PORT)
    r.recvuntil(b'> ')
    r.sendline(b'ciphertext_info')
    output = b''
    while not output.strip().endswith(b'>'):
        output += r.recv(timeout=2)
    r.close()
    lines = output.decode(errors='ignore').splitlines()
    N, e, c = None, None, None
    for line in lines:
        if line.startswith('N = '):
            N = int(line.strip().split(' = ')[1])
        elif line.startswith('e = '):
            e = int(line.strip().split(' = ')[1])
        elif line.startswith('c = '):
            c = int(line.strip().split(' = ')[1])
    if N is None or e is None or c is None:
        raise Exception('Parsing error! Got lines: {}'.format(lines))
    return (N, e, c)

def main():
    samples = []
    for _ in range(SAMPLES):
        nsample = get_sample()
        print(f'Collected sample N={nsample[0]:x} e={nsample[1]:x}')
        samples.append(nsample)
    # Check for repeated moduli and direct GCD collisions
    seen = {}
    for i in range(SAMPLES):
        N1 = samples[i][0]
        for j in range(i+1, SAMPLES):
            N2 = samples[j][0]
            g = gcd(N1, N2)
            if g != 1 and g != N1 and g != N2:
                print(f'GCD(N_{i},N_{j}) = {g}')
    # Now check GCD(Ni-1, Nj-1)
    for i in range(SAMPLES):
        N1 = samples[i][0]
        for j in range(i+1, SAMPLES):
            N2 = samples[j][0]
            h = gcd(N1-1, N2-1)
            if h > 1:
                print(f'GCD(N_{i}-1, N_{j}-1) = {h}')
    # Print all N, e, c tuples for analysis
    print('----- Dumped N, e, c tuples:')
    for tup in samples:
        print('N =', tup[0])
        print('e =', tup[1])
        print('c =', tup[2])
        print('-----')

if __name__ == '__main__':
    main()
